import 'package:uuid/uuid.dart';

import '../domain/event.dart';
import '../domain/text_actor.dart';
import '../storage/task_store.dart';
import '../text/native_text_engine.dart';
import 'agent_profile.dart';

/// Whole-action text Undo for an agent installation across process restarts
/// (design/agent-interface-feasibility.md, "Restart-safe text Undo").
///
/// Each agent field context uses one deterministic Undo allocation, so every
/// earlier own Undo can be regenerated byte-for-byte. The private native
/// document is rebuilt from the canonical lineage: the root seed, own edits as
/// owned receipts named by their event IDs, peer packets as remote updates and
/// own earlier Undos replayed through prepare + exact-bytes check + commit.
/// Any mismatch refuses the whole Undo before anything is appended.
class AgentTextUndo {
  AgentTextUndo(this.store, this.engine, this.writer);
  final TaskStore store;
  final NativeTextEngine engine;
  final String writer;

  static String undoAllocation(String writer, String context) =>
      const Uuid().v5(writer, 'tandemlog.agent.undo:$context');

  /// Compensation `changes` for [target] (a `task.textEdited` by [writer]).
  Future<Map<String, dynamic>> prepare(LogEvent target) async {
    final edited = (target.data['changes'] as Map).cast<String, dynamic>();
    final lineage = await store.textLineage(target.entity);
    final changes = <String, dynamic>{};
    for (final field in edited.keys) {
      final history = lineage[field];
      if (history == null) {
        throw const AgentFailure(
          'undo_unavailable',
          'This text history is not available yet. Nothing was changed.',
        );
      }
      changes[field] = _prepareField(field, history, target);
    }
    return changes;
  }

  Map<String, dynamic> _prepareField(
    String field,
    TaskTextLineage history,
    LogEvent target,
  ) {
    final context = history.context;
    if (history.operations.any((op) => op.claim.context != context)) {
      // Inherited (recurring successor) lineages span several contexts; the
      // proven reconstruction covers one context only.
      throw const AgentFailure(
        'undo_unavailable',
        'Undo of text inherited from an earlier occurrence is not available. Nothing was changed.',
      );
    }
    final allocation = undoAllocation(writer, context);
    final actor = deriveTextActor(context, writer, allocation);
    final document = engine.createDocument(
      actorClientId: actor,
      limits: NativeTextLimits(visibleUtf16: field == 'title' ? 500 : 10000),
      seed: history.seed,
    );
    try {
      var found = false;
      for (final op in history.operations) {
        final own = op.event.writer == writer;
        if (own && op.event.type == 'task.textEditUndone') {
          if (op.claim.actor != actor) {
            throw const AgentFailure(
              'undo_unavailable',
              'An earlier Undo of this text was made elsewhere. Nothing was changed.',
            );
          }
          final prepared = document.prepareOperationUndo(
            operationId: op.event.data['operation'] as String,
          );
          if (prepared.update.encoded != op.update.encoded) {
            prepared.cancel();
            throw const AgentFailure(
              'undo_unavailable',
              'Earlier Undo history could not be reproduced exactly. Nothing was changed.',
            );
          }
          prepared.commit(receiptUpdate: op.update);
        } else if (own) {
          document.applyOwnedReceipt(op.update, operationId: op.event.id);
          found |= op.event.id == target.id;
        } else {
          document.applyRemote(op.update);
        }
      }
      if (!found) {
        throw const AgentFailure(
          'undo_unavailable',
          'This text edit is not in the current history. Nothing was changed.',
        );
      }
      if (document.read().pending) {
        throw const AgentFailure(
          'undo_unavailable',
          'Text history is waiting for a missing update. Nothing was changed.',
        );
      }
      final prepared = document.prepareOperationUndo(operationId: target.id);
      final update = prepared.update.encoded;
      prepared.cancel();
      return {
        'context': context,
        'allocation': allocation,
        'actor': actor,
        'update': update,
      };
    } finally {
      document.dispose();
    }
  }
}
